pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }

    function testFuzz_property(address admin) public {
        vm.assume(admin != address(0));

        bool initialPaused;
        try c.paused() returns (bool v) { initialPaused = v; } catch { initialPaused = false; }

        assertTrue(!initialPaused);
    }
}
